import React from 'react';
import { Link } from 'react-router-dom';
import '../styles/pages/Home.scss';
import siteData from '../data/siteData.json';

const Home = () => {
  const { homePage } = siteData;
  const { hero, servicesPreview, whyUs } = homePage;

  return (
    <div className="home">
      <section className="hero">
        <div className="container">
          <div className="hero__content">
            <h1>{hero.title}</h1>
            <p>{hero.subtitle}</p>
            <Link to="/contact" className="btn btn-primary">{hero.cta}</Link>
          </div>
        </div>
      </section>

      <section className="services-preview">
        <div className="container">
          <h2>{servicesPreview.title}</h2>
          <div className="services-grid">
            {servicesPreview.services.map((service, index) => (
              <div key={index} className="service-card">
                <div className="service-card__icon">{service.icon}</div>
                <h3>{service.title}</h3>
                <p>{service.description}</p>
              </div>
            ))}
          </div>
          <div className="services-preview__cta">
            <Link to="/services" className="btn btn-secondary">{servicesPreview.cta}</Link>
          </div>
        </div>
      </section>

      <section className="why-us">
        <div className="container">
          <h2>{whyUs.title}</h2>
          <div className="features-grid">
            {whyUs.features.map((feature, index) => (
              <div key={index} className="feature">
                <h3>{feature.title}</h3>
                <p>{feature.description}</p>
              </div>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
};

export default Home;
